#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-06

# check-built-manifest.sh
#
# CI gate guarding against the v0.3.0 regression, where a build step dropped
# the `mcpServers` block from the built plugin.json relative to the source
# manifest it was generated from.
#
# --- Where the "source of truth" manifest actually lives (verified) ---
# This repo's build model is NOT "src/.claude-plugin/plugin.json -> plugins/.../plugin.json".
# There is no plugin.json under src/. Instead:
#
#   SOURCE (pre-build) manifest : manifests/academic-writer.json
#     - hand-maintained; carries name/version/description/author/... AND the
#       full `mcpServers` block.
#
#   BUILT (post-build) manifest : plugins/academic-writer/.claude-plugin/plugin.json
#     - generated by `scripts/build-plugins.sh` (Phase 4) via a `jq` transform
#       that reads manifests/academic-writer.json and re-emits only the
#       schema-recognized plugin.json keys, INCLUDING mcpServers when present:
#         jq '{name, version, description, author, homepage, repository,
#              license, keywords} + (if .mcpServers then {mcpServers: .mcpServers} else {} end)'
#       This is exactly the code path that regressed in v0.3.0 (the
#       `+ (if .mcpServers then ... end)` merge was the fix — an earlier
#       version of this transform silently omitted mcpServers whenever it
#       fell through a different code path).
#
# This script therefore diffs manifests/academic-writer.json (source) against
# plugins/academic-writer/.claude-plugin/plugin.json (built), specifically
# asserting mcpServers exists and is non-empty in BOTH, and that the built
# mcpServers block is present whenever the source declares one.
#
# The full build is NOT re-run automatically by this script (it assumes
# `npm run build` / `bash scripts/build-plugins.sh` has already been run, or
# that you are checking the currently-committed built output as-is). Pass
# --build to run the build first.
#
# Exit 0 -> built plugin.json has a non-empty mcpServers block matching source's presence
# Exit 1 -> built plugin.json is missing mcpServers (or it's empty) while source has one

set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"

SOURCE_MANIFEST="$PROJECT_ROOT/manifests/academic-writer.json"
BUILT_MANIFEST="$PROJECT_ROOT/plugins/academic-writer/.claude-plugin/plugin.json"

RED='\033[0;31m'
GREEN='\033[0;32m'
BLUE='\033[0;34m'
NC='\033[0m'

fail() {
  echo -e "${RED}✗ check-built-manifest: $1${NC}" >&2
  exit 1
}

if [[ "${1:-}" == "--build" ]]; then
  echo -e "${BLUE}Running build (scripts/build-plugins.sh) before checking...${NC}"
  bash "$PROJECT_ROOT/scripts/build-plugins.sh" || fail "build failed, cannot check built manifest"
fi

[[ -f "$SOURCE_MANIFEST" ]] || fail "source manifest not found at $SOURCE_MANIFEST"
[[ -f "$BUILT_MANIFEST" ]] || fail "built manifest not found at $BUILT_MANIFEST (run \`npm run build\` first, or pass --build)"

command -v jq &>/dev/null || fail "jq is required for this check"

SOURCE_HAS_MCP=$(jq 'has("mcpServers") and (.mcpServers | length > 0)' "$SOURCE_MANIFEST")
BUILT_HAS_MCP=$(jq 'has("mcpServers") and (.mcpServers | length > 0)' "$BUILT_MANIFEST")

echo "source manifest  ($SOURCE_MANIFEST): mcpServers present & non-empty = $SOURCE_HAS_MCP"
echo "built  manifest  ($BUILT_MANIFEST): mcpServers present & non-empty = $BUILT_HAS_MCP"

if [[ "$SOURCE_HAS_MCP" == "true" && "$BUILT_HAS_MCP" != "true" ]]; then
  fail "regression detected: source manifest declares a non-empty mcpServers block but the built plugin.json is missing it (or it's empty). This is the v0.3.0 regression class — re-check scripts/build-plugins.sh's jq transform in Phase 4."
fi

if [[ "$SOURCE_HAS_MCP" == "true" ]]; then
  SOURCE_SERVER_NAMES=$(jq -S '.mcpServers | keys' "$SOURCE_MANIFEST")
  BUILT_SERVER_NAMES=$(jq -S '.mcpServers | keys' "$BUILT_MANIFEST")
  if [[ "$SOURCE_SERVER_NAMES" != "$BUILT_SERVER_NAMES" ]]; then
    fail "mcpServers key set differs between source and built manifest. source keys: $SOURCE_SERVER_NAMES  built keys: $BUILT_SERVER_NAMES"
  fi
fi

echo -e "${GREEN}✓ check-built-manifest: built plugin.json's mcpServers block matches source manifest${NC}"
exit 0
